/* =========================================
     [設定] CSS変数とテーマ
========================================= */

:root {
      --bg-color: #f8fafc;
      --text-main: #555555;
      --text-muted: #64748b;
      --card-bg: transparent;
      --border: #e2e8f0;
      --accent: #1e3a5f;
      --accent-hover: #e97834;
      --base-navy: #1e3a5f;
      --sub-amber: #f59e0b;
      --bq-bg: #f3f3f3;
      --bq-border: #c4c4c4;
      --radius: 8px;
      --shadow: none;
      --shadow-hover: none;
      --header-bg: #800000;
      --sidebar-width: 300px;
      --max-width: 1225px;
      --tab-text-active: #333;
      --tab-text-muted: #aaaaaa;
      --tab-lamp-color: #333;
      --tab-border-color: #eeeeee;
      color-scheme: light;
   }
.post-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 2.5rem 1rem;
      align-items: stretch
}
/* =========================================
     CSS
========================================= */
*, *::before, *::after {
   box-sizing: border-box
}
body {
   margin: 0;
   padding: 0;
   font-family: 'Inter', system-ui, -apple-system, sans-serif;
   background-color: var(--bg-color);
   color: var(--text-main);
   line-height: 1.6
}
.site-header {
    background-image: radial-gradient(rgba(255, 255, 255, 0.2) 1px, transparent 1px), 
    url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhVZbMAogx2LneA2z_8LuHLg8NI6wiruiwl98SftmpYTJwPE-2-tvWlpn4hzbgqWhd9E_OQ1YCnhTvxp0nOwhgZrQE7yoPrM6BYWn8w2HTWn_uFjHbr_yOiS3keIKM1IWlrUxFWJTTOy9EPITk3v2BsUgPhlpUwQg9KjMQKKtH8ge3GbbnAUc0TYGDjQgw/w1920/aig-esports_7525009-xl_TP_V.webp);
    
    background-size: 3px 3px, cover;
    background-position: center;
    background-repeat: repeat, no-repeat;
    width: 100% !important;
    min-height: 250px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px 0;
    position: relative;
}

.site-header > * {
    opacity: 0 !important;
    transition: opacity 0.1s ease !important; 
}

.site-header.is-loaded > * {
    opacity: 1 !important;
}

.site-header::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 40px;
    height: 40px;
    margin: -20px 0 0 -20px;
    border: 3px solid rgba(30, 58, 95, 0.15); /* --accent の薄い色 */
    border-top-color: var(--accent);
    border-radius: 50%;
    animation: header-spin 1s linear infinite;
    opacity: 1;
    transition: opacity 0.3s ease;
    z-index: 10;
}

.site-header.is-loaded::before {
    opacity: 0;
    pointer-events: none;
}

@keyframes header-spin {
    to { transform: rotate(360deg); }
}
.header-inner {
   max-width: var(--max-width);
   margin: 0 auto;
   padding: 0 1.5rem;
   display: flex;
   flex-direction: column;
   align-items: center;
   justify-content: center;
   position: relative;
   text-align: center;
   height: 100%
}
.site-title {
   margin: 0 0 0.5rem 0;
   font-size: 2rem;
   font-weight: 700;
   letter-spacing: -0.01em;
   color: white
}
.site-title a {
   text-decoration: none;
   color: white;
   font-family: "Fira Sans", sans-serif;
   font-weight: 700;
}
.site-description {
   margin: 0;
   font-size: 1rem;
   color: rgba(255, 255, 255, 0.9);
   font-weight: 300
}
.global-nav {
   position: sticky;
   top: 0;
   z-index: 999;
   background: var(--header-bg);
   border-bottom: 1px solid var(--border)
}
.global-nav-inner {
   max-width: var(--max-width);
   margin: 0 auto;
   padding: 0 1.5rem 0 0;
   display: flex;
   align-items: center;
   height: 50px
}
.theme-toggle {
   background: none;
   border: none;
   cursor: pointer;
   color: white;
   padding: 0.5rem;
   display: flex;
   align-items: center;
   justify-content: center;
   border-radius: 50%;
   transition: background 0.2s;
   margin-left: 0.5rem
}
.theme-toggle:hover {
   background: rgba(128, 128, 128, 0.1)
}
.theme-toggle svg {
   width: 20px;
   height: 20px
}
.bookmark-wrapper {
   position: relative;
   margin-left: 0.5rem;
   flex-shrink: 0
}
.bookmark-list-btn {
   background: none;
   border: none;
   cursor: pointer;
   color: white;
   padding: 0.5rem;
   display: flex;
   align-items: center;
   justify-content: center;
   border-radius: 50%;
   transition: background 0.2s;
   position: relative
}
.bookmark-list-btn:hover {
   background: rgba(128, 128, 128, 0.1)
}
.bookmark-list-btn svg {
   width: 20px;
   height: 20px
}
.bookmark-list-btn .bm-badge {
   position: absolute;
   top: 4px;
   right: 4px;
   background: var(--accent);
   color: white;
   font-size: 0.65rem;
   font-weight: 700;
   width: 16px;
   height: 16px;
   border-radius: 50%;
   display: flex;
   align-items: center;
   justify-content: center;
   pointer-events: none;
   display: none
}
.bookmark-list-btn.has-bookmarks .bm-badge {
   display: flex
}
.bookmark-panel {
   position: absolute;
   top: calc(100% + 8px);
   right: 0;
   background: var(--bg-color);
   border: 1px solid var(--border);
   border-radius: var(--radius);
   padding: 0.5rem 0;
   width: 300px;
   opacity: 0;
   visibility: hidden;
   transform: translateY(-6px);
   transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
   box-shadow: 0 10px 25px -5px rgba(0,0,0,0.15);
   z-index: 9999;
   max-height: 420px;
   overflow-y: auto
}
.bookmark-wrapper.open .bookmark-panel {
   opacity: 1;
   visibility: visible;
   transform: translateY(0)
}
.bookmark-panel-header {
   display: flex;
   align-items: center;
   justify-content: space-between;
   padding: 0.5rem 1rem 0.6rem;
   border-bottom: 1px solid var(--border);
   font-size: 0.8rem;
   font-weight: 700;
   color: var(--text-main)
}
.bookmark-panel-clear {
   background: none;
   border: none;
   cursor: pointer;
   font-size: 0.75rem;
   color: var(--text-muted);
   padding: 0;
   transition: color 0.2s
}
.bookmark-panel-clear:hover {
   color: var(--accent)
}
.bookmark-panel-empty {
   padding: 1.5rem 1rem;
   text-align: center;
   font-size: 0.82rem;
   color: var(--text-muted)
}
.bookmark-panel-list {
   list-style: none;
   margin: 0;
   padding: 0.3rem 0
}
.bookmark-panel-item {
   display: flex;
   align-items: center;
   gap: 0.5rem;
   padding: 0.45rem 1rem;
   transition: background 0.15s
}
.bookmark-panel-item:hover {
   background: rgba(128,128,128,0.06)
}
.bookmark-panel-item a {
   flex: 1;
   font-size: 0.82rem;
   color: var(--text-main);
   text-decoration: none;
   line-height: 1.4;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden
}
.bookmark-panel-item a:hover {
   color: var(--accent)
}
.bookmark-panel-remove {
   background: none;
   border: none;
   cursor: pointer;
   color: var(--text-muted);
   padding: 0;
   display: flex;
   align-items: center;
   flex-shrink: 0;
   transition: color 0.2s
}
.bookmark-panel-remove:hover {
   color: var(--accent)
}
.bookmark-panel-remove svg {
   width: 14px;
   height: 14px
}
.meta-bookmark-btn {
   background: none;
   border: none;
   cursor: pointer;
   color: var(--text-muted);
   padding: 0;
   display: inline-flex;
   align-items: center;
   gap: 0.4rem;
   font-size: 0.85rem;
   transition: color 0.2s;
   margin-left: auto
}
.meta-bookmark-btn:hover {
   color: var(--accent)
}
.meta-bookmark-btn svg {
   width: 14px;
   height: 14px;
   transition: fill 0.2s, stroke 0.2s
}
.meta-bookmark-btn.bookmarked {
   color: var(--accent)
}
.meta-bookmark-btn.bookmarked svg {
   fill: var(--accent);
   stroke: var(--accent)
}
.translate-btn {
   background: none;
   border: none;
   cursor: pointer;
   color: white;
   padding: 0.5rem;
   display: flex;
   align-items: center;
   justify-content: center;
   border-radius: 50%;
   transition: background 0.2s;
   margin-left: 0.5rem;
   position: relative
}
.translate-btn:hover {
   background: rgba(128, 128, 128, 0.1)
}
.translate-btn svg {
   width: 20px;
   height: 20px
}
.translate-dropdown {
   position: absolute;
   top: calc(100% + 8px);
   right: 0;
   background: var(--bg-color);
   border: 1px solid var(--border);
   border-radius: var(--radius);
   padding: 0.4rem 0;
   min-width: 170px;
   opacity: 0;
   visibility: hidden;
   transform: translateY(-6px);
   transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
   box-shadow: 0 10px 25px -5px rgba(0,0,0,0.15);
   z-index: 9999
}
.translate-btn.open .translate-dropdown {
   opacity: 1;
   visibility: visible;
   transform: translateY(0)
}
.translate-dropdown a {
   display: flex;
   align-items: center;
   gap: 0.5rem;
   padding: 0.5rem 1rem;
   color: var(--text-main);
   text-decoration: none;
   font-size: 0.85rem;
   font-weight: 500;
   transition: 0.15s;
   white-space: nowrap
}
.translate-dropdown a:hover {
   background: rgba(128,128,128,0.07);
   color: var(--accent)
}
.translate-dropdown a .lang-flag {
   font-size: 1rem
}
.goog-te-banner-frame,
.goog-te-banner-frame.skiptranslate,
#goog-gt-tt,
.goog-tooltip,
.goog-te-balloon-frame,
.skiptranslate > iframe {
   display: none !important;
   visibility: hidden !important
}
body {
   top: 0 !important;
   position: static !important
}
.goog-te-menu-frame {
   box-shadow: none !important
}
.header-nav {
   display: flex;
   align-items: center;
   gap: 1.8rem;
   margin-left: 1.5rem;
   flex-grow: 1;
   height: 65px;
}
.nav-link {
   text-decoration: none;
   color: white;
   font-size: 0.9rem;
   font-weight: 600;
   transition: 0.2s;
   padding: 1rem 0;
   opacity: 0.9
}
.nav-link:hover {
   opacity: 1;
   color: var(--accent-hover)
}
.has-dropdown {
   position: relative
}
.has-dropdown:not(.has-mega)::after {
   content: '';
   position: absolute;
   top: 100%;
   left: 0;
   right: 0;
   height: 12px;
   background: transparent
}
.dropdown-menu {
   position: absolute;
   top: 132% !important;
   left: 0;
   background: var(--bg-color);
   border: 1px solid var(--border);
   border-radius: var(--radius);
   padding: 0.5rem 0;
   min-width: 160px;
   opacity: 0;
   visibility: hidden;
   transform: translateY(-6px);
   transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);
   z-index: 1000
}
.has-dropdown:hover .dropdown-menu {
   opacity: 1;
   visibility: visible;
   transform: translateY(0)
}
.dropdown-item {
   display: block;
   padding: 0.6rem 1.2rem;
   color: var(--text-main);
   text-decoration: none;
   font-size: 0.85rem;
   font-weight: 500;
   transition: 0.2s
}
.dropdown-item:hover {
   background: rgba(128, 128, 128, 0.05);
   color: var(--accent)
}
@media (max-width:900px) {
  .header-nav {
    display: none
  }
  .theme-toggle {
    margin-left: 0 
  }
  .translate-btn {
    margin-left: auto !important;
  }
}
.menu-toggle {
   display: none;
   background: none;
   border: none;
   cursor: pointer;
   padding: 0.5rem;
   color: white
}
.menu-icon {
   width: 24px;
   height: 2px;
   background: white;
   position: relative;
   display: block
}
.menu-icon::before, .menu-icon::after {
   content: '';
   position: absolute;
   width: 100%;
   height: 100%;
   background: white;
   left: 0;
   transition: 0.3s
}
.menu-icon::before {
   top: -6px
}
.menu-icon::after {
   top: 6px
}
.mobile-nav {
   position: fixed;
   top: 0;
   left: -100%;
   width: 280px;
   height: 100vh;
   background: var(--bg-color);
   z-index: 1000;
   box-shadow: 20px 0 40px rgba(0, 0, 0, 0.1);
   transition: left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   padding: 2rem 1.5rem;
   overflow-y: auto
}
.mobile-nav.is-active {
   left: 0
}
.nav-overlay {
   position: fixed;
   top: 0;
   left: 0;
   width: 100%;
   height: 100%;
   background: rgba(0, 0, 0, 0.5);
   z-index: 999;
   display: none;
   backdrop-filter: blur(4px)
}
.nav-overlay.is-active {
   display: block
}
.layout-container {
   max-width: var(--max-width);
   margin: 2rem auto;
   padding: 0 1.5rem;
   display: grid;
   grid-template-columns: 1fr var(--sidebar-width);
   gap: 45px;
   align-items: start
}
@media (max-width:900px) {
   .layout-container {
      grid-template-columns: 1fr
   }
   .menu-toggle {
      display: block
   }
}
.sidebar {
   position: sticky;
   top: 80px;
   height: fit-content
}
@media (max-width:1024px) {
   .post-grid {
      grid-template-columns: repeat(2, 1fr)
   }
}
@media (max-width:600px) {
   .post-grid {
      grid-template-columns: 1fr
   }
}
.post-card {
   background: var(--card-bg);
   border-radius: 0;
   overflow: visible;
   box-shadow: var(--shadow);
   transition: transform 0.2s ease;
   display: flex;
   flex-direction: column;
   height: 100%;
   min-height: 280px
}
.post-thumbnail-wrapper {
   width: 100%;
   aspect-ratio: 16/10;
   border-radius: var(--radius);
   overflow: hidden;
   background: linear-gradient(90deg, var(--border) 25%, var(--bg-color) 50%, var(--border) 75%);
   background-size: 200% 100%;
   animation: shimmer 1.5s infinite linear
}
.post-thumbnail {
   width: 100%;
   height: 100%;
   object-fit: cover;
   transition: transform 0.3s ease
}
.post-card:hover .post-thumbnail {
   transform: scale(1.05)
}
.highlight-post {
   display: grid;
   grid-template-columns: repeat(3, 1fr);
   gap: 1.5rem;
   margin-top: 3rem;   
   margin-bottom: 3rem;
   text-decoration: none;
   color: inherit;
   padding-bottom: 2rem;
   padding-top: 2rem;
   border-bottom: 1px solid var(--border);
   border-top: 1px solid var(--border);
}
.hp-thumb-link {
   grid-column: span 1;
   border-radius: var(--radius);
   overflow: hidden;
   height: fit-content
}
.hp-thumb-link .post-thumbnail-wrapper {
   margin-bottom: 0;
   aspect-ratio: 16/10
}
.hp-content {
   grid-column: span 2;
   display: flex;
   flex-direction: column;
   padding: 0.2rem 0
}
.hp-title {
   font-size: 1.8rem;
   font-weight: 800;
   line-height: 1.2;
   margin: 0 0 0.8rem;
   color: var(--text-main)
}
.hp-summary {
   font-size: 0.95rem;
   color: var(--text-muted);
   margin-bottom: 1.2rem;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
   line-height: 1.6
}
.hp-footer {
   display: flex;
   align-items: center;
   flex-wrap: wrap;
   gap: 12px;
   margin-top: auto;
   font-size: 0.8rem;
   color: var(--text-muted);
   padding-top: 15px
}
.hp-label {
   color: var(--text-muted);
   padding: 2px 8px;
   border-radius: 4px;
   font-weight: 600;
   font-size: 0.7rem
}
.hp-author-wrap {
   display: flex;
   align-items: center;
   gap: 8px;
   color: var(--text-muted);
   font-weight: 600
}
.hp-author-img {
   width: 22px;
   height: 22px;
   border-radius: 50%;
   object-fit: cover;
   background: var(--border)
}
.hp-readmore {
   margin-left: auto;
   color: var(--accent);
   font-weight: 700
}
.highlight-post:hover .post-thumbnail {
   transform: scale(1.05)
}
.highlight-post:hover .hp-title {
   color: var(--accent)
}
@media (max-width:1024px) {
   .highlight-post {
      grid-template-columns: 1fr 1fr
   }
   .hp-thumb-link {
      grid-column: span 1
   }
   .hp-content {
      grid-column: span 1
   }
   .hp-title {
      font-size: 1.4rem
   }
}
@media (max-width:600px) {
   .highlight-post {
      grid-template-columns: 1fr
   }
   .hp-thumb-link, .hp-content {
      grid-column: span 1
   }
}
.post-content {
   padding: 0.8rem 0 0 0;
   flex-grow: 1;
   display: flex;
   flex-direction: column;
   min-height: 120px
}
.post-labels {
   margin-bottom: 0.5rem;
   display: flex;
   gap: 0.5rem;
   flex-wrap: wrap
}
.post-label-item {
   font-size: 0.75rem;
   color: var(--accent);
   font-weight: 500;
   display: inline-flex;
   align-items: center
}
.post-title {
   margin: 0 0 0.4rem;
   font-size: 1rem;
   line-height: 1.4;
   color: var(--text-main);
   font-weight: 700;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
   text-overflow: ellipsis
}
.post-summary {
   margin: 0;
   font-size: 14px;
   color: var(--text-muted);
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden
}
.post-footer {
   margin-top: auto;
   padding-top: 1rem;
   display: flex;
   justify-content: space-between;
   align-items: center;
   font-size: 0.8rem;
   color: var(--text-muted)
}
.post-date {
   display: inline-flex;
   align-items: center
}
.post-readmore {
   font-weight: 600;
   color: var(--accent);
   transition: color 0.2s
}
.post-link {
   text-decoration: none;
   color: inherit;
   display: flex;
   flex-direction: column;
   height: 100%
}
.search-widget {
   margin-bottom: 2.5rem
}
.search-form {
   position: relative;
   display: flex;
   align-items: center;
   background: var(--bg-color);
   border: 1px solid var(--border);
   border-radius: 50px;
   padding: 2px 4px 2px 15px;
   transition: border-color 0.3s, box-shadow 0.3s;
   overflow: hidden;
   box-sizing: border-box
}
.search-form:focus-within {
   border-color: var(--accent);
   box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
   background: #eff6ff
}
.search-input {
   flex: 1;
   border: none;
   background: transparent;
   padding: 8px 0;
   font-size: 0.9rem;
   color: var(--text-main);
   outline: none;
   -webkit-box-shadow: 0 0 0px 1000px transparent inset;
   box-shadow: 0 0 0px 1000px transparent inset;
   -webkit-text-fill-color: var(--text-main)
}
.search-input::placeholder {
   color: var(--text-muted);
   opacity: 0.7
}
.header-search .search-input::placeholder {
   color: rgba(255,255,255,0.35);
   opacity: 1;
   -webkit-text-fill-color: rgba(255,255,255,0.35)
}
.search-submit {
   background: var(--accent);
   color: white;
   border: none;
   width: 32px;
   height: 32px;
   min-width: 32px;
   flex-shrink: 0;
   border-radius: 50%;
   display: flex;
   align-items: center;
   justify-content: center;
   cursor: pointer;
   transition: background 0.2s;
   box-sizing: border-box;
   padding: 0
}
.search-submit:hover {
   background: var(--accent-hover)
}
a {
   color: var(--accent);
   text-decoration: none;
   transition: color 0.2s ease, opacity 0.2s ease
}
a:hover {
   color: var(--accent-hover);
   text-decoration: none
}
.post-body a:hover {
   text-decoration: underline
}
.post-content a {
   border-bottom: 1px solid var(--border)
}
.post-content a:hover {
   border-bottom-color: var(--accent-hover);
   background-color: rgba(180, 83, 9, 0.05)
}
.tags {
   display: grid;
   grid-template-columns: repeat(2, 1fr);
   gap: 0.4rem
}
.tag:not(.token) {
   font-size: 0.75rem;
   font-weight: 500;
   padding: 0.3rem 0.4rem;
   background: rgba(37, 99, 235, 0.08);
   color: var(--accent);
   border-radius: 3px;
   text-decoration: none;
   transition: background 0.2s;
   text-align: left;
   overflow: hidden;
   text-overflow: ellipsis;
   white-space: nowrap
}
.tag:not(.token):hover {
   background: rgba(37, 99, 235, 0.15)
}
.sidebar-widget {
   background: var(--card-bg);
   border-radius: 0;
   padding: 0;
   box-shadow: var(--shadow);
   margin-bottom: 2.5rem
}
.widget-title {
   position: relative;
   background: rgba(128, 128, 128, 0.10);
   padding: 0.3em 0.3em 0.3em 1.4em;
   color: var(--text-main)
}
.widget-title::after {
   position: absolute;
   top: 50%;
   left: 0;
   transform: translateY(-50%);
   content: '';
   width: 18px;
   height: 4px;
   background-color: var(--header-bg)
}
.recent-posts-list {
   list-style: none;
   padding: 0;
   margin: 0
}
.recent-post-item {
   margin-bottom: 1.2rem;
   list-style: none;
   padding: 0;
   border: none
}
.recent-post-link {
   display: flex !important;
   gap: 12px;
   text-decoration: none;
   color: inherit;
   align-items: flex-start
}
.recent-post-thumb {
   width: 50px;
   height: 50px;
   border-radius: 6px;
   object-fit: cover;
   flex-shrink: 0;
   background: var(--border)
}
.recent-post-info {
   min-width: 0;
   padding-top: 1px;
   flex: 1
}
.recent-post-title {
   font-size: 0.85rem;
   font-weight: 600;
   line-height: 1.4;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
   margin-bottom: 0.25rem;
   color: var(--text-main);
   transition: color 0.2s
}
.recent-post-link:hover .recent-post-title {
   color: var(--accent)
}
.recent-post-meta {
   display: flex;
   flex-wrap: wrap;
   gap: 8px;
   align-items: center
}
.recent-post-meta .meta-item {
   display: inline-flex;
   align-items: center;
   gap: 4px;
   font-size: 0.7rem;
   color: var(--text-muted)
}
.recent-post-meta svg {
   width: 10px;
   height: 10px;
   fill: currentColor;
   opacity: 0.8
}
.tabs-header {
   display: flex;
   position: relative;
   border-bottom: 2px solid var(--tab-border-color);
   margin-bottom: 15px;
   cursor: pointer
}
.tab-item {
   flex: 1;
   text-align: center;
   padding: 12px 0;
   font-size: 14px;
   font-weight: 700;
   color: var(--tab-text-muted);
   transition: color 0.3s
}
.tab-item.active {
   color: var(--tab-text-active)
}
.tab-lamp {
   position: absolute;
   bottom: -2px;
   left: 0;
   width: 50%;
   height: 2px;
   background: var(--tab-lamp-color);
   transition: transform 0.3s
}
.panel {
   display: none
}
.panel.active {
   display: block
}
.post-full {
   background: var(--card-bg);
   padding: 0;
   box-shadow: var(--shadow)
}
.post-breadcrumbs {
   font-size: 0.85rem;
   color: var(--text-muted);
   margin-bottom: 1.2rem
}
.post-breadcrumbs a {
   color: inherit;
   text-decoration: none
}
.post-breadcrumbs a:hover {
   color: var(--accent)
}
.post-full-header {
   margin-bottom: 1.5rem;
   padding-bottom: 1.5rem;
   border-bottom: 1px solid var(--border)
}
.post-full-title {
   font-size: 2.2rem;
   line-height: 1.3;
   margin: 0 0 1.5rem;
   font-weight: 800;
   color: var(--text-main)
}
.post-full-meta {
   display: flex;
   flex-wrap: wrap;
   gap: 1rem 1.5rem;
   align-items: center;
   font-size: 0.85rem;
   color: var(--text-muted)
}
.meta-item {
   display: inline-flex;
   align-items: center;
   gap: 0.4rem;
   text-decoration: none;
   color: inherit
}
.meta-item a:hover {
   color: var(--accent)
}
.author-info {
   display: inline-flex;
   align-items: center;
   gap: 0.5rem
}
.author-avatar {
   width: 24px;
   height: 24px;
   border-radius: 50%;
   object-fit: cover;
   background: var(--border)
}
.post-body {
   font-size: 1.05rem;
   line-height: 1.8;
   color: var(--text-main);
   min-width: 0;
   overflow-x: clip;
   padding-bottom: 2rem;
}
