blockquote{
    position:relative;
    border-top:1px solid var(--base-navy);
    border-bottom:1px solid var(--base-navy);
    padding:10px;
}
blockquote:before {
    position: absolute;
    background-color: #f8fafc;
    color: var(--base-navy);
    font-family: 'FontAwesome';
    content: '\f10d';
    line-height: 1;
    text-align: center;
    top: -20px;
    left: -10px;
    padding: 10px;
    font-size: 20px;
}
blockquote:after {
    position: absolute;
    right: -10px;
    bottom: -20px;
    background-color: #f8fafc;
    padding: 10px;
    color: var(--base-navy);
    font-family: 'FontAwesome';
    content: '\f10e';
    line-height: 1;
    text-align: center;
    font-size: 20px;
}
blockquote cite {
    display: block;
    padding-right:30px;
    font-size: 0.8rem;
    text-align: right;
    color: #808080;
}

code {
   font-family: 'Consolas', 'Menlo', 'Monaco', monospace;
   font-size: 0.88em;
   padding: 0.15em 0.45em;
   border-radius: 4px
}
pre:not([class*="language-"]) {
   font-family: 'Consolas', 'Menlo', 'Monaco', monospace;
   font-size: 0.9em;
   line-height: 1.6;
   background: #1e293b;
   color: #e2e8f0;
   padding: 1.2rem 1.4rem;
   border-radius: var(--radius);
   overflow-x: auto;
   white-space: pre-wrap;
   max-width: 100%;
   box-sizing: border-box;
   -webkit-overflow-scrolling: touch;
   word-break: normal;
   overflow-wrap: normal;
   display: block;
   width: 100%
}
pre:not([class*="language-"]) code {
   background: none;
   padding: 0 !important;
   border-radius: 0;
   font-size: inherit;
   color: inherit;
   word-break: normal !important;
   overflow-wrap: normal !important;
   white-space: inherit
}

pre[class*="language-"] {
   font-family: 'Consolas', 'Menlo', 'Monaco', monospace;
   font-size: 0.9em;
   line-height: 1.6;
   background: #1e293b;
   color: #f1f5f9;
   padding: 1.2rem 1.4rem;
   border-radius: var(--radius);
   overflow-x: auto;
   white-space: pre-wrap;
   max-width: 100%;
   box-sizing: border-box;
   -webkit-overflow-scrolling: touch;
   word-break: normal;
   overflow-wrap: normal;
   display: block;
   width: 100%;
   border: none !important;
   box-shadow: none !important;
   text-shadow: none !important
}

pre[class*="language-"] code[class*="language-"] {
   background: none !important;
   color: inherit !important;
   padding: 0 !important;
   border-radius: 0;
   font-size: inherit;
   word-break: normal !important;
   overflow-wrap: normal !important;
   white-space: inherit;
   text-shadow: none !important
}
pre[class*="language-"] .token.comment,
pre[class*="language-"] .token.prolog,
pre[class*="language-"] .token.doctype,
pre[class*="language-"] .token.cdata { color: #c4c4c4 !important }
pre[class*="language-"] .token.punctuation { color: #f1f5f9 !important; opacity: .7 }
pre[class*="language-"] .token.boolean,
pre[class*="language-"] .token.number,
pre[class*="language-"] .token.tag,
pre[class*="language-"] .token.deleted { color: var(--accent-hover) !important;}
pre[class*="language-"] .token.keyword,
pre[class*="language-"] .token.property,
pre[class*="language-"] .token.selector,
pre[class*="language-"] .token.constant,
pre[class*="language-"] .token.symbol,
pre[class*="language-"] .token.builtin { color: #f9ed99 !important }
pre[class*="language-"] .token.attr-name,
pre[class*="language-"] .token.attr-value,
pre[class*="language-"] .token.string,
pre[class*="language-"] .token.char,
pre[class*="language-"] .token.operator,
pre[class*="language-"] .token.entity,
pre[class*="language-"] .token.url,
pre[class*="language-"] .token.variable,
pre[class*="language-"] .token.inserted { color: #14971e !important; }
pre[class*="language-"] .token.atrule { color: #7385a5 !important }
pre[class*="language-"] .token.regex,
pre[class*="language-"] .token.important { color: #e8c062 !important }
pre[class*="language-"] .token.function { color: #e8c062 !important }
.post-body img {
   max-width: 100% !important;
   height: auto !important;
   margin-left: auto;
   margin-right: auto;
   border-radius: var(--radius)
}
.post-body pre, .post-body pre code, .post-body code {
   aspect-ratio: unset !important;
   height: auto !important;
   object-fit: unset !important
}
.post-body table {
   width: 100%;
   border-collapse: collapse;
   margin: 1.5rem 0;
   font-size: 0.9rem
}
.post-body th, .post-body td {
   padding: 10px 14px;
   text-align: left;
   border: 1px solid var(--border);
   vertical-align: top
}
.post-body th {
   background: rgba(128, 128, 128, 0.07);
   font-weight: 700;
   color: var(--text-muted)
}
.post-body tr:last-child td {
   border-bottom: 1px solid var(--border)
}
@media (max-width:600px) {
   .post-body table:not([class]) thead {
      display: none
   }
   .post-body table:not([class]) tr {
      display: block;
      margin-bottom: 1rem;
      border: 1px solid var(--border);
      border-radius: var(--radius)
   }
   .post-body table:not([class]) td {
      display: block;
      text-align: right;
      padding-left: 50%;
      position: relative;
      border: none;
      border-bottom: 1px solid var(--border)
   }
   .post-body table:not([class]) td::before {
      content: attr(data-label);
      position: absolute;
      left: 14px;
      width: 45%;
      text-align: left;
      font-weight: 700;
      color: var(--text-muted)
   }
}
.separator {
   max-width: 100% !important;
   height: auto !important
}
.separator a {
   max-width: 100% !important;
   display: block
}
.author-profile {
   margin: 1rem 0 2rem;
   padding: 1.5rem;
   background: rgba(128, 128, 128, 0.05);
   border-radius: var(--radius);
   display: flex;
   gap: 1.2rem;
   align-items: center
}
.author-profile img {
   width: 64px;
   height: 64px;
   border-radius: 50%;
   object-fit: cover;
   flex-shrink: 0;
   background: var(--border)
}
.author-profile-info {
   flex-grow: 1
}
.author-profile-info h3 {
   margin: 0 0 0.4rem;
   font-size: 1.1rem;
   font-weight: 700;
   color: var(--text-main)
}
.author-profile-info p {
   margin: 0;
   font-size: 0.85rem;
   color: var(--text-muted);
   line-height: 1.5
}
.author-social {
   display: flex;
   gap: 15px;
   margin-top: 12px
}
.author-social a {
   color: var(--text-muted);
   font-size: 1.1rem;
   transition: 0.2s;
   text-decoration: none
}
.author-social a:hover {
   color: var(--accent);
   transform: translateY(-2px)
}
.aChp {
   display: flex;
   gap: 1rem;
   margin: 2rem 0
}
.aChp a {
   flex: 1;
   text-decoration: none;
   color: inherit;
   padding: 1rem;
   border: 1px solid var(--border);
   border-radius: var(--radius);
   display: flex;
   flex-direction: column;
   gap: 0.3rem;
   transition: 0.2s;
   min-width: 0
}
.aChp a:hover {
   background: rgba(128, 128, 128, 0.05);
   border-color: var(--accent)
}
.aChp .n {
   text-align: right
}
.aChp .b {
   font-size: 0.7rem;
   font-weight: 700;
   text-transform: uppercase;
   color: var(--text-muted);
   letter-spacing: 0.05em
}
.aChp .t {
   font-size: 0.9rem;
   font-weight: 600;
   display: -webkit-box;
   -webkit-line-clamp: 1;
   -webkit-box-orient: vertical;
   overflow: hidden;
   color: var(--text-main)
}
.pSh {
   margin: 2.5rem 0;
   padding-top: 1.5rem;
   border-top: 1px solid var(--border)
}
.pShc {
   display: flex;
   gap: 10px;
   align-items: center;
   flex-wrap: wrap;
   position: relative;
   font-size: 13px;
   color: var(--text-muted)
}
.pShc::before {
   content: attr(data-text);
   font-weight: 700;
   color: var(--text-main);
   margin-right: 5px
}
.pShc a, .pShc label, .share-modal-content a.c {
   display: flex;
   align-items: center;
   justify-content: center;
   width: 36px;
   height: 36px;
   border-radius: 50%;
   background: var(--border);
   color: var(--text-main);
   transition: all 0.2s;
   cursor: pointer;
   text-decoration: none
}
.pShc a svg, .pShc label svg, .share-modal-content a.c svg {
   width: 20px;
   height: 20px;
   fill: currentColor
}
.c.fb:hover {
   background: #1877f2;
   color: white
}
.c.wa:hover {
   background: #25d366;
   color: white
}
.c.tw:hover {
   background: #000000;
   color: white
}
.c.hb:hover {
   background: #00a4de;
   color: #fff
}
.c.ln:hover {
   background: #06c755;
   color: #fff
}
.c.hb .hb-icon {
   font-family: "Arial Black", sans-serif;
   font-size: 16px;
   font-weight: 900;
   line-height: 1;
   display: block
}
.c.hb:hover {
   background: #00a4de;
   color: #fff
}
.pShc label:hover {
   background: var(--accent);
   color: white
}
#forShare {
   display: none
}
.share-modal {
   position: fixed;
   inset: 0;
   z-index: 1000;
   background: rgba(0, 0, 0, 0.5);
   backdrop-filter: blur(4px);
   display: none;
   align-items: center;
   justify-content: center;
   padding: 1.5rem
}
#forShare:checked~.share-modal {
   display: flex
}
.share-modal-content {
   background: var(--bg-color);
   border: 1px solid var(--border);
   border-radius: var(--radius);
   width: 100%;
   max-width: 400px;
   padding: 1.5rem;
   box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
   position: relative;
   animation: modalIn 0.3s ease-out
}
@keyframes modalIn {
   from {
      opacity: 0;
      transform: translateY(10px)
   }
   to {
      opacity: 1;
      transform: translateY(0)
   }
}
.share-modal-title {
   margin: 0 0 1.5rem;
   font-size: 1.1rem;
   font-weight: 700
}
.share-modal-close {
   position: absolute;
   top: 1rem;
   right: 1rem;
   cursor: pointer;
   font-size: 1.2rem
}
.copy-link-box {
   display: flex;
   gap: 8px;
   margin-top: 1.5rem;
   padding: 10px;
   background: rgba(128, 128, 128, 0.1);
   border-radius: var(--radius);
   align-items: center
}
.copy-link-input {
   flex: 1;
   border: none;
   font-size: 0.85rem;
   background: none;
   color: var(--text-muted);
   overflow: hidden;
   white-space: nowrap;
   text-overflow: ellipsis
}
.copy-link-btn {
   background: var(--accent);
   color: white;
   border: none;
   padding: 6px 14px;
   border-radius: 6px;
   cursor: pointer;
   font-size: 0.8rem;
   font-weight: 600;
   transition: background 0.3s
}
.copy-link-btn.success {
   background: #10b981 !important
}
.share-btn-list {
   display: flex;
   justify-content: center;
   gap: 12px;
   margin-bottom: 20px;
   flex-wrap: wrap
}
.share-btn-list .c {
   display: flex;
   align-items: center;
   justify-content: center;
   width: 36px;
   height: 36px;
   border-radius: 50%;
   background: var(--border);
   color: var(--text-main);
   transition: 0.2s
}
.share-btn-list .c svg {
   width: 20px;
   height: 20px;
   fill: currentColor
}
.share-btn-list .tw:hover {
   background: #000;
   color: #fff
}
.share-btn-list .fb:hover {
   background: #1877f2;
   color: #fff
}
.related-posts-section {
   margin: 3rem 0
}
.related-posts-title {
   font-size: 1.2rem;
   font-weight: 800;
   margin-bottom: 1.5rem;
   color: var(--text-main)
}
@media (max-width:768px) {
   .related-grid .post-card:nth-child(n+4) {
      display: none
   }
}
#comments-placeholder {
   margin-top: 3rem;
   padding-top: 2rem;
   border-top: 1px solid var(--border)
}
.comments h4 {
   font-size: 1.2rem;
   margin-bottom: 1.5rem;
   color: var(--text-main)
}
.comment-thread {
   list-style: none;
   padding: 0
}
.comment-block {
   margin-bottom: 1.5rem;
   padding: 1rem;
   background: rgba(128, 128, 128, 0.05);
   border-radius: var(--radius)
}
.comment-header {
   font-size: 0.9rem;
   font-weight: 600;
   margin-bottom: 0.5rem;
   color: var(--text-main)
}
.comment-header a {
   color: var(--text-main);
   text-decoration: none
}
.comment-content {
   font-size: 0.95rem;
   color: var(--text-main);
   line-height: 1.6
}
.comment-actions a {
   color: var(--accent);
   font-size: 0.8rem;
   text-decoration: none;
   font-weight: 500
}
.comment-replybox-single {
   margin-top: 1.5rem
}
iframe.blogger-iframe-colorize {
   border-radius: var(--radius) !important;
   width: 100% !important;
   border: 1px solid var(--border) !important;
   background: transparent !important
}

:root {
   --body-bg-color: var(--bg-color);
   --body-text-color: var(--text-main)
}


