.site-footer {
   text-align: center;
   padding: 3rem 1.5rem;
   color: var(--text-muted);
   border-top: 1px solid var(--border);
   margin-top: 4rem
}
.footer-navigation {
   margin-bottom: 15px;
   display: flex;
   justify-content: center;
   flex-wrap: nowrap;
   gap: 5px
}
.footer-navigation a {
   text-decoration: none;
   color: inherit;
   font-size: 14px;
   white-space: nowrap
}
.footer-navigation a:hover {
   color: var(--accent-hover)
}
.footer-navigation .separator {
   font-size: 12px;
   color: var(--text-muted)
}
#designed-by a {
   color: inherit;
   text-decoration: none
}
#designed-by a:hover {
   color: var(--accent-hover)
}
#designed-by:before {
   content: "M-StruX designed by "
}
@media screen and (max-width:768px) {
   .footer-navigation a {
      font-size: 10px
   }
   .footer-navigation .separator {
      font-size: 9px
   }
}
