      font-size: 10px
   }
   .footer-navigation .separator {
      font-size: 9px
   }
}
.pagination {
   display: flex;
   justify-content: center;
   align-items: center;
   gap: 8px;
   margin-top: 4rem;
   flex-wrap: wrap;
   padding-bottom: 2rem
}
.pagination a, .pagination span {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   min-width: 40px;
   height: 40px;
   padding: 0 8px;
   border: 1px solid var(--border);
   border-radius: var(--radius);
   text-decoration: none;
   color: var(--text-main);
   font-weight: 600;
   font-size: 0.9rem;
   transition: all 0.2s;
   background: var(--card-bg)
}
.pagination a:hover {
   border-color: var(--header-bg);
   color: var(--header-bg);
}
.pagination .current {
   background: var(--header-bg);
   color: white;
   border-color: var(--header-bg);
   pointer-events: none
}
.pagination .disabled {
   opacity: 0.3;
   cursor: not-allowed;
   pointer-events: none
}
.pagination .dots {
   border: none;
   background: transparent;
   cursor: default
}
@media (max-width:600px) {
   .pagination {
      gap: 6px
   }
   .pagination a, .pagination span {
      min-width: 36px;
      height: 36px;
      font-size: 0.8rem
   }
}
#hidden-label-widget {
   position: absolute;
   top: -9999px;
   left: -9999px;
   width: 1px;
   height: 1px;
   overflow: hidden
}
.raw-label, .hp-data, .feat-data {
   display: none
}

#ContactForm1 .contact-form-widget {
   position: absolute;
   left: -9999px;
   top: -9999px;
   width: 1px;
   height: 1px;
   overflow: hidden;
   opacity: 0;
   pointer-events: none
}
.view-status {
   padding: 1.2rem 0;
   margin-bottom: 2rem;
   border-top: 1px solid var(--border);
   border-bottom: 1px solid var(--border);
   font-size: 0.95rem;
   color: var(--text-main);
   line-height: 1.5;
   display: flex;
   align-items: center;
   gap: 10px;
   flex-wrap: wrap
}
.view-status i {
   color: var(--accent);
   font-size: 1.1rem
}
.view-status b {
   color: var(--accent);
   font-weight: 700
}
.entry-tag {
   margin: 0.5rem 0;
   display: flex;
   flex-wrap: wrap;
   gap: 0.5rem;
}
.entry-tag-container {
    margin: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-top: 1rem;
    border-top: 1px solid var(--border);
}

.like-wrapper {
    margin-left: 0;
}
.reaction-bar {
    margin-left: auto;
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
}
.hatena-star-container {
    display: inline-flex;
    align-items: center;
}
.hashtag-pill {
   display: block;
   padding: 0.3rem 0.4rem;
   background: rgba(128, 128, 128, 0.08);
   color: var(--text-main);
   border-radius: 3px;
   font-size: 0.85rem;
   font-weight: 500;
   text-decoration: none;
   transition: 0.2s;
   text-align: left;
   overflow: hidden;
   text-overflow: ellipsis;
   white-space: nowrap
}
.hashtag-pill:hover {
   background: var(--accent);
   color: white;
   transform: translateY(-2px)
}
#loading {
   display: none;
   text-align: center;
   padding: 4rem;
   color: var(--text-muted);
   animation: pulse 1.5s infinite
}
@keyframes pulse {
   0%, 100% {
      opacity: 1
   }
   50% {
      opacity: 0.5
   }
}
.comments-accordion {
   margin-top: 2rem;
   border-top: 1px solid var(--border);
   padding-top: 2rem
}
#forComments {
   display: none
}
.cmShw {
   text-align: center;
   margin-bottom: 1rem
}
.cmBtn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   padding: 0.8rem 2.5rem;
   background: var(--accent);
   color: white;
   border-radius: 50px;
   font-weight: 700;
   cursor: pointer;
   transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
   box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1)
}
.cmBtn:hover {
   background: var(--accent-hover);
   transform: translateY(-2px);
   box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1)
}
.comment-content-wrap {
   max-height: 0;
   overflow: hidden;
   transition: max-height 0.5s ease-in-out, opacity 0.5s;
   opacity: 0
}
#forComments:checked~.comment-content-wrap {
   max-height: 800px;
   opacity: 1;
   padding-top: 1.5rem
}
#forComments:checked~.cmShw .cmBtn {
   background: var(--text-muted)
}
#forComments:checked~.cmShw .cmBtn::after {
   content: 'を閉じる';
   margin-left: 5px
}
.blsm-feat {
   display: flex;
   gap: 20px;
   max-width: var(--max-width);
   margin: 2rem auto;
   padding: 0 1.5rem
}
.blsm-first {
   flex: 0 0 60%;
   position: relative;
   border-radius: 10px;
   overflow: hidden;
   aspect-ratio: 16 / 10;
   background: linear-gradient(90deg, var(--border) 25%, var(--bg-color) 50%, var(--border) 75%);
   background-size: 200% 100%;
   animation: shimmer 1.5s infinite linear
}
.blsm-rest-wrap {
   flex: 1;
   display: flex;
   flex-direction: column;
   gap: 20px
}
.blsm-rest {
   flex: 1;
   position: relative;
   border-radius: 10px;
   overflow: hidden;
   aspect-ratio: 16 / 8;
   background: linear-gradient(90deg, var(--border) 25%, var(--bg-color) 50%, var(--border) 75%);
   background-size: 200% 100%;
   animation: shimmer 1.5s infinite linear
}
.blsm-img {
   display: block;
   width: 100%;
   height: 100%;
   background-size: cover;
   background-position: center;
   transition: transform 0.5s;
   position: relative;
   border-radius: 0
}
.blsm-img:hover {
   transform: scale(1.05)
}
.tyimg-lay {
   position: absolute;
   inset: 0;
   background: radial-gradient(rgba(0, 0, 0, 0.3) 30%, transparent 31%), radial-gradient(rgba(0, 0, 0, 0.3) 30%, transparent 31%);
   background-size: 4px 4px;
   background-position: 0 0, 2px 2px
}
.blsm-con-blossom, .blossom-tent-ty {
   position: absolute;
   bottom: 0;
   left: 0;
   padding: 1.5rem;
   color: white;
   width: 100%;
