}
.blsm-con-blossom *, .blossom-tent-ty * {
   pointer-events: auto
}
.blossom-label {
   margin-bottom: 0.6rem
}
.blossom-label a {
   background: var(--accent);
   color: white;
   padding: 5px 10px;
   font-size: 0.7rem;
   font-weight: 700;
   border-radius: 4px;
   text-decoration: none;
   text-transform: uppercase
}
.blossomt-title {
   margin: 0 0 0.5rem;
   font-size: 1.6rem;
   line-height: 1.2;
   font-weight: 800;
   letter-spacing: -0.02em
}
.blossomt-title a {
   color: var(--accent);
   text-decoration: none;
	  text-shadow:2px 2px 0 #FFF, -2px -2px 0 #FFF,
              -2px 2px 0 #FFF, 2px -1px 0 #FFF,
              0px 2px 0 #FFF,  0-2px 0 #FFF,
              -2px 0 0 #FFF, 2px 0 0 #FFF;
}
.blossomt-title a:hover {
   text-decoration: none
}
.blsm-rest .blossomt-title {
   font-size: 1.1rem
}
.blsm-time {
   font-size: 0.75rem;
   opacity: 0.8
}
.blossom-auth-ty {
   font-size: 0.75rem;
   font-weight: 600;
