}
@media (max-width:900px) {
   .blsm-feat {
      flex-direction: column;
      padding: 0 10px;
      gap: 15px
   }
   .blsm-first {
      flex: none;
      width: 100%;
      height: 280px
   }
   .blsm-rest-wrap {
      height: auto;
      gap: 15px
   }
