      font-size: 1rem
   }
}
.post-list-wrap {
   display: flex;
   flex-direction: column;
   gap: 1rem
}
.post-item-list {
   background: var(--card-bg);
   border-radius: var(--radius);
   overflow: hidden;
   border: 1px solid var(--border);
   transition: border-color 0.2s
}
.post-item-list:hover {
   border-color: var(--accent)
}
.list-link {
   display: flex;
   flex-direction: column;
   text-decoration: none;
   color: inherit
}
.list-thumb {
   width: 100%;
   aspect-ratio: 16 / 9;
   overflow: hidden;
   background: linear-gradient(90deg, var(--border) 25%, var(--bg-color) 50%, var(--border) 75%);
   background-size: 200% 100%;
   animation: shimmer 1.5s infinite linear
}
.list-thumb-inner {
   width: 100%;
   height: 100%
}
.list-thumb-inner img {
   width: 100%;
   height: 100%;
   object-fit: cover;
   transition: transform 0.3s ease
}
.post-item-list:hover .list-thumb-inner img {
   transform: scale(1.05)
}
.list-content {
   padding: 1rem;
   display: flex;
   flex-direction: column;
   gap: 0.4rem
}
.list-title {
   margin: 0;
   font-size: 1rem;
   font-weight: 700;
   line-height: 1.4;
   color: var(--text-main);
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
   min-height: calc(1rem * 1.4 * 2)
}
.list-summary {
   margin: 0.5rem 0 0;
   font-size: 0.9rem;
   color: var(--text-muted);
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden
}
.list-footer {
   display: flex;
   align-items: center;
   gap: 12px;
   font-size: 0.8rem;
   color: var(--text-muted);
   margin-top: 0.4rem
}
.list-date {
   display: inline-flex;
   align-items: center
}
.list-readmore {
   margin-left: auto;
   font-weight: 600;
   color: var(--accent)
}
@media (min-width:768px) {
   .list-link {
      flex-direction: row;
      align-items: stretch
   }
   .list-thumb {
      width: 240px;
      min-width: 240px;
      aspect-ratio: unset;
      height: auto
   }
   .list-content {
      flex: 1;
      justify-content: center;
      padding: 1.2rem
   }
   .list-title {
      font-size: 1.1rem
   }
}
.dropdown-menu {
   position: absolute;
   top: 100%;
   left: 0;
   background: var(--bg-color);
   border: 0px solid var(--border);
   border-top: 4px solid var(--header-bg);
   border-radius: 0 0 var(--radius) var(--radius);
   padding: 0.5rem 0;
   min-width: 160px;
   opacity: 0;
   visibility: hidden;
   transition: opacity 0.3s ease, visibility 0.3s ease;
   box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
   z-index: 1000;
   margin-top: 0
}
.has-dropdown:hover .dropdown-menu {
   opacity: 1;
   visibility: visible
}
.dropdown-item {
   display: block;
   padding: 0.6rem 1.2rem;
   color: var(--text-main);
   text-decoration: none;
   font-size: 0.85rem;
   font-weight: 500;
   transition: 0.2s;
   white-space: nowrap
}
.dropdown-item:hover {
   background: rgba(128, 128, 128, 0.05);
   color: var(--accent)
}
.mega-dropdown {
   position: fixed;
   top: 40px;
   left: 50%;
   transform: translateX(-50%);
   width: min(var(--max-width), 100vw);
   background: var(--bg-color);
   border: 0px solid var(--border);
   border-top: 0px solid var(--header-bg);
   border-radius: 0 0 var(--radius) var(--radius);
   box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
   opacity: 0;
   visibility: hidden;
   transition: opacity 0.3s ease, visibility 0.3s ease;
   z-index: 1000;
   pointer-events: none;
   margin-top: 0
}
.has-mega:hover .mega-dropdown {
   opacity: 1;
   visibility: visible;
   pointer-events: auto
}
.mega-grid {
   display: grid;
   grid-template-columns: repeat(4, 1fr);
   gap: 1rem;
   padding: 1rem
}
.mega-item {
   display: block;
   text-decoration: none;
   color: inherit;
   border-radius: var(--radius);
   overflow: hidden;
   position: relative;
   aspect-ratio: 16/10;
   background: var(--border);
   transition: transform 0.2s ease
}
.mega-item:hover {
   transform: scale(1.02)
}
.mega-thumb {
   width: 100%;
   height: 100%;
   object-fit: cover;
   display: block;
   position: absolute;
   inset: 0;
   border-radius: var(--radius)
}
.mega-thumb-placeholder {
   width: 100%;
   height: 100%;
   background: var(--border);
   display: flex;
   align-items: center;
   justify-content: center;
   font-size: 0.7rem;
   color: var(--text-muted)
}
.mega-item-overlay {
   position: absolute;
   inset: 0;
   background: linear-gradient(to top, rgba(0, 0, 0, 0.75) 0%, rgba(0, 0, 0, 0.3) 50%, transparent 100%);
   border-radius: var(--radius)
}
.mega-item-body {
   position: absolute;
   bottom: 0;
   left: 0;
   right: 0;
   padding: 0.6rem 0.7rem
}
.mega-item-label {
   font-size: 0.65rem;
   color: rgba(255, 255, 255, 0.75);
   font-weight: 600;
   margin-bottom: 0.2rem;
   display: flex;
   align-items: center
}
.mega-item-title {
   font-size: 0.8rem;
   font-weight: 700;
   line-height: 1.3;
   color: #fff;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
   text-shadow: 0 1px 3px rgba(0, 0, 0, 0.4)
}
.mega-footer {
   border-top: 1px solid var(--border);
   padding: 0.6rem 1rem;
   text-align: right
}
.mega-footer a {
   font-size: 0.8rem;
   color: var(--accent);
   font-weight: 600;
   text-decoration: none
}
.mega-footer a:hover {
   color: var(--accent-hover)
}
.mega-loading {
   grid-column: span 4;
   padding: 2rem;
   text-align: center;
   color: var(--text-muted);
   font-size: 0.85rem
}
.mega-loading .loading-spinner {
   display: inline-block;
   width: 28px;
   height: 28px;
   border: 3px solid var(--border);
   border-top-color: var(--accent);
   border-radius: 50%;
   animation: spin 0.8s linear infinite
}
@media (max-width:900px) {
   .mega-dropdown {
      display: none !important
   }
}
.adsense-slot {
