.infeed-blog-card {
   display: flex;
   flex-direction: column;
   margin: 2em auto;
   box-shadow: 0 4px 20px -5px rgba(0, 0, 0, 0.1);
   background: var(--if-bg);
   line-height: 1.4;
   font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
   border-radius: 10px;
   overflow: hidden;
   text-decoration: none !important;
   max-width: 800px;
   transition: all 0.3s ease;
   border: 1px solid rgba(0, 0, 0, 0.05);
}
.infeed-blog-card:hover {
   transform: translateY(-3px);
   box-shadow: 0 12px 25px -10px rgba(0, 0, 0, 0.2);
}
.infeed-blog-card .meta {
   position: relative;
   z-index: 0;
   height: 180px;
   overflow: hidden;
   background-color: #f0f0f0;
}
.infeed-blog-card .photo {
   position: absolute;
   top: 0;
   right: 0;
   bottom: 0;
   left: 0;
   background-size: cover;
   background-position: center;
   transition: transform 0.6s cubic-bezier(0.25, 1, 0.5, 1);
}
.infeed-blog-card:hover .photo {
   transform: scale(1.1);
}
.infeed-blog-card .description {
   padding: 1.2rem 1.5rem;
   background: var(--if-bg);
   position: relative;
   z-index: 1;
   display: flex;
   flex-direction: column;
   justify-content: center;
}
.infeed-blog-card .label-container {
   display: flex;
   flex-wrap: wrap;
   gap: 10px;
   margin-bottom: 6px;
}
.infeed-blog-card .category-label {
   font-size: 0.7rem;
   font-weight: 600;
   text-transform: uppercase;
   color: var(--if-label);
   letter-spacing: 0.5px;
   display: flex;
   align-items: center;
}
.infeed-blog-card .category-label i {
   margin-right: 4px;
   font-size: 0.65rem;
}
.infeed-blog-card h3 {
   line-height: 1.2;
   margin: 0;
   font-size: 1.25rem;
   color: var(--if-title);
   font-weight: 700;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
}
.infeed-blog-card p {
   position: relative;
   margin: 1.1rem 0 0;
   font-size: 0.9rem;
   color: var(--if-text);
   line-height: 1.5;
   display: -webkit-box;
   -webkit-line-clamp: 2;
   -webkit-box-orient: vertical;
   overflow: hidden;
}
.infeed-blog-card p:before {
   content: "";
   position: absolute;
   height: 3px;
   background: var(--if-prime);
