  (function() {
    function detectSingleItem() {
      return /\/[0-9]{4}\/[0-9]{2}\/[^\/]+\.html/.test(window.location.href)
          || document.body.classList.contains('item-view');
    }
    function buildSidebarRandom() {
      var single = detectSingleItem();
      var postCount = single ? 5 : 3;
      var blogURL = window.location.protocol + '//' + window.location.hostname + '/';
      fetch(blogURL + 'feeds/posts/default?alt=json&max-results=50')
        .then(function(r){ return r.json(); })
        .then(function(data) {
          var entries = (data.feed && data.feed.entry) || [];
          if (!entries.length) return;
          var picked = [], len = entries.length;
          while (picked.length < Math.min(len, postCount)) {
            var r = Math.floor(Math.random() * len);
            if (picked.indexOf(r) === -1) picked.push(r);
          }
          var noImg = 'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiPDYu4ibLWCVdJdTwQa2zoBViIfND-ZB0Y9g8IU1Csk_7AoRwVi1efzTdGFKjaiXh9LPWyCllES9iKlhik8b2G2liUUd8oeAA4NOVflZO3VqPtxhzuUteSAIGCRkyw2Ps8R5FjyFd1FzhmgPYCeAUGBM2qx3Z-lXUGUft6xgiKGUORq3Uz2ULqbSZFEsQ/s1600/NoImage.png';
          var html = '';
          if (single) {
            picked.forEach(function(idx) {
              var e = entries[idx];
              var title = e.title.$t;
              var link = '';
              for (var k = 0; k < e.link.length; k++) {
                if (e.link[k].rel === 'alternate') { link = e.link[k].href; break; }
              }
              var img = noImg;
              if (e.media$thumbnail) img = e.media$thumbnail.url.replace(/\/s[0-9]+(-c)?/, '/w200');
              html += '<a href="' + link + '" style="display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);text-decoration:none;">'
                + '<img src="' + img + '" alt="" style="width:52px;height:52px;min-width:52px;object-fit:cover;border-radius:6px;background:#eee;" loading="lazy"/>'
                + '<span style="flex:1;font-size:13px;font-weight:bold;color:var(--text-main);line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;">' + title + '</span>'
                + '</a>';
            });
          } else {
            picked.forEach(function(idx) {
              var e = entries[idx];
              var title = e.title.$t;
              var link = '';
              for (var k = 0; k < e.link.length; k++) {
                if (e.link[k].rel === 'alternate') { link = e.link[k].href; break; }
              }
              var img = noImg;
              if (e.media$thumbnail) img = e.media$thumbnail.url.replace(/\/s[0-9]+(-c)?/, '/w600');
              html += '<a href="' + link + '" style="display:block;position:relative;width:100%;aspect-ratio:16/9;margin-bottom:14px;border-radius:8px;overflow:hidden;text-decoration:none;">'
                + '<img src="' + img + '" alt="" style="width:100%;height:100%;object-fit:cover;background:#eee;" loading="lazy"/>'
                + '<div style="position:absolute;bottom:0;left:0;right:0;padding:24px 12px 10px;background:linear-gradient(transparent,rgba(0,0,0,0.78));">'
                + '<span style="display:block;font-size:13px;font-weight:bold;color:#fff;line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-shadow:1px 1px 3px rgba(0,0,0,.5);">' + title + '</span>'
                + '</div></a>';
            });
          }
          var el = document.getElementById('sidebar-random-posts-list');
          if (el) el.innerHTML = html || '<span style="color:var(--text-muted);">記事が見つかりませんでした</span>';
        })
        .catch(function(err) { console.error('Sidebar Random Posts Error:', err); });
    }
    var _lastHref = '';
    function initSidebarRandom() {
      _lastHref = window.location.href;
      buildSidebarRandom();
      setInterval(function() {
        if (window.location.href !== _lastHref) {
          _lastHref = window.location.href;
          setTimeout(buildSidebarRandom, 300);
        }
      }, 500);
    }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', initSidebarRandom);
    } else {
      initSidebarRandom();
    }
